class ScalerMini:
    """Meniru StandardScaler untuk satu kolom: (x - rata) / simpangan."""

    def fit(self, X):
        n = len(X)
        self.rata = sum(X) / n
        self.simpangan = (sum((x - self.rata) ** 2 for x in X) / n) ** 0.5
        return self

    def transform(self, X):
        return [(x - self.rata) / self.simpangan for x in X]


class CentroidMini:
    """Model sederhana: tebak kelas yang rata-ratanya paling dekat."""

    def fit(self, X, y):
        self.pusat = {}
        for kelas in sorted(set(y)):
            anggota = [x for x, label in zip(X, y) if label == kelas]
            self.pusat[kelas] = sum(anggota) / len(anggota)
        return self

    def predict(self, X):
        return [min(self.pusat, key=lambda k: abs(x - self.pusat[k]))
                for x in X]


class PipelineMini:
    def __init__(self, scaler, model):
        self.scaler, self.model = scaler, model

    def fit(self, X, y):
        X_skala = self.scaler.fit(X).transform(X)   # fit di data latih saja
        self.model.fit(X_skala, y)
        return self

    def predict(self, X):
        return self.model.predict(self.scaler.transform(X))   # tanpa fit


