def relu(z):
    return max(0.0, z)


def sigmoid(z):
    return 1 / (1 + math.exp(-z))


def lapisan(x, W, b, aktivasi):
    # tiap baris W adalah bobot satu neuron
    return [aktivasi(sum(xi * wi for xi, wi in zip(x, baris)) + bi)
            for baris, bi in zip(W, b)]


