def bentuk(x):
    # bentuk (shape) list bersarang, seperti tensor.shape
    hasil = []
    while isinstance(x, list):
        hasil.append(len(x))
        x = x[0]
    return tuple(hasil)


def kali(x, k):
    # operasi elemen demi elemen, seperti tensor * k
    if isinstance(x, list):
        return [kali(v, k) for v in x]
    return x * k


