def rrf(*peringkat, k=60):
    """Gabungkan beberapa daftar peringkat dengan Reciprocal Rank Fusion."""
    skor = {}
    for daftar in peringkat:
        for posisi, dok in enumerate(daftar, 1):
            skor[dok] = skor.get(dok, 0) + 1 / (k + posisi)
    return sorted(skor.items(), key=lambda p: (-p[1], p[0]))


