def recall_at_k(hasil, relevan, k):
    return len(set(hasil[:k]) & relevan) / len(relevan)


def reciprocal_rank(hasil, relevan):
    for posisi, dok in enumerate(hasil, 1):
        if dok in relevan:
            return 1 / posisi
    return 0.0


