def jejak(nama):
    """Dekorator: catat setiap pemanggilan fungsi sebagai span."""
    def bungkus(fungsi):
        @functools.wraps(fungsi)
        def dalam(*args):
            global kedalaman
            span = {"nama": nama, "tingkat": kedalaman, "masuk": args}
            JEJAK.append(span)
            kedalaman += 1
            try:
                hasil = fungsi(*args)
                span["keluar"] = hasil
                return hasil
            finally:
                kedalaman -= 1
        return dalam
    return bungkus


